<script setup>
import { onMounted, reactive, ref } from 'vue';
import Icon from '../components/Icon.vue'; import Avatar from '../components/Avatar.vue'; import Modal from '../components/Modal.vue';
import { user, config, token, data, canEdit, registerAccount, notify } from '../store.js'; import { request } from '../services/api.js'; import { ROLES, idEqual } from '../domain.js';
const accounts = ref([]), loading = ref(false), error = ref(''), editing = ref(false), form = reactive({}), saving = ref(false), formError = ref('');
async function load() { if (!canEdit.value) return; loading.value = true; error.value = ''; try { { const rows = await request(config.baseUrl, '/users', { token: token.value }); if (!Array.isArray(rows)) throw new Error('Ресурс users должен возвращать массив.'); accounts.value = rows.map(x => ({ id: x.id, fullName: x.fullName, email: x.email, role: x.role, departmentId: x.departmentId })); } } catch (e) { error.value = e.message; } finally { loading.value = false; } }
function edit(account) { Object.keys(form).forEach(k => delete form[k]); Object.assign(form, account || { fullName: '', email: '', password: '', role: 'security', departmentId: data.departments[0]?.id || '' }); editing.value = true; formError.value = ''; }
async function submit() { saving.value = true; formError.value = ''; try { if (!canEdit.value) throw new Error('Недостаточно прав.'); if (form.role === 'manager' && !form.departmentId) throw new Error('Выберите подразделение.'); if (form.id != null) { await request(config.baseUrl, `/users/${encodeURIComponent(form.id)}`, { method: 'PATCH', token: token.value, body: { fullName: form.fullName.trim(), role: form.role, departmentId: form.role === 'manager' ? form.departmentId : null } }); } else await registerAccount(form); editing.value = false; form.password = ''; notify('Учётная запись сохранена.'); await load(); } catch (e) { formError.value = e.message; } finally { saving.value = false; } }
onMounted(load);
</script>
<template><div class="page-header"><div><span class="eyebrow">ДОСТУП К ВЕБ-ИНТЕРФЕЙСУ</span><h1>Пользователи<span class="heading-dot">.</span></h1><p>Учётные записи администратора, службы безопасности и руководителей.</p></div><button v-if="config.mode === 'mokky'" class="button primary" @click="edit()"><Icon name="plus" :size="18" />Добавить пользователя</button></div><div v-if="error" class="alert-box" role="alert">{{ error }} <button class="text-button" @click="load">Повторить</button></div><section class="panel"><div v-if="loading" class="empty-state"><Icon name="loader" class="spin" :size="30" /><p>Загружаем пользователей…</p></div><div v-else-if="!accounts.length" class="empty-state"><Icon name="shield" :size="34" /><h3>Нет данных о пользователях</h3><p>Проверьте доступ к ресурсу users.</p></div><div v-else class="table-scroll"><table class="data-table"><thead><tr><th>Пользователь</th><th>Email</th><th>Роль</th><th>Подразделение</th><th></th></tr></thead><tbody><tr v-for="account in accounts" :key="account.id"><td><div class="person-cell"><Avatar :person="account" /><strong>{{ account.fullName }}</strong><span v-if="idEqual(account.id, user.id)" class="badge neutral">Вы</span></div></td><td>{{ account.email || '—' }}</td><td><span class="badge" :class="account.role === 'admin' ? 'green' : 'neutral'">{{ ROLES[account.role] || 'Роль не назначена' }}</span></td><td>{{ account.role === 'manager' ? data.departments.find(d => idEqual(d.id, account.departmentId))?.name || 'Не назначено' : 'Все подразделения' }}</td><td><button v-if="config.mode === 'mokky' && !idEqual(account.id, user.id)" class="icon-button" aria-label="Редактировать пользователя" @click="edit(account)"><Icon name="edit" :size="17" /></button></td></tr></tbody></table></div></section><Modal v-if="editing" :title="form.id != null ? 'Редактировать пользователя' : 'Новый пользователь'" @close="!saving && (editing = false)"><form id="account-form" class="form-grid" @submit.prevent="submit"><label class="span-2">Имя пользователя<input v-model="form.fullName" required maxlength="100" /></label><label v-if="form.id == null" class="span-2">Email<input v-model="form.email" type="email" required autocomplete="off" /></label><label v-if="form.id == null" class="span-2">Пароль<input v-model="form.password" type="password" required minlength="8" autocomplete="new-password" /><small class="muted">Не менее 8 символов</small></label><label class="span-2">Роль<select v-model="form.role"><option v-for="(name, key) in ROLES" :key="key" :value="key">{{ name }}</option></select></label><label v-if="form.role === 'manager'" class="span-2">Подразделение<select v-model="form.departmentId" required><option value="" disabled>Выберите подразделение</option><option v-for="d in data.departments" :key="d.id" :value="d.id">{{ d.name }}</option></select></label><div v-if="formError" class="alert-box span-2" role="alert">{{ formError }}</div></form><template #footer><button class="button" :disabled="saving" @click="editing = false">Отмена</button><button class="button primary" form="account-form" type="submit" :disabled="saving">{{ saving ? 'Сохраняем…' : 'Сохранить' }}</button></template></Modal></template>
